{
  "decline_reason": "",
  "claims": [
    {
      "text": "Section 217A requires the Registrar to make prescribed documents relating to a trade mark available for public inspection while held in the Trade Marks Office at or after publication of the application particulars under section 30.",
      "quotes": [
        {
          "ref": "TMA1995/s217A",
          "quote": "(1) The Registrar must make available for public inspection prescribed documents that relate to a trade mark while they are held in the Trade Marks Office at or after the time particulars of the application for registration of the trade mark are published under section 30."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual says most documents relating to a trade mark application are publicly accessible, with copies obtainable on payment of a fee if the documents are prescribed for section 217A.",
      "quotes": [
        {
          "ref": "TMM/Part61/1/1/1",
          "quote": "1.1.1 Most documents in relation to a trade mark application will be made available for public access. This means that interested parties can obtain copies of trade mark documents provided that they pay a fee and that the documents are considered prescribed for the purposes of section 217A of the Trade Mark Act"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual says anyone can request all or specific documents on file without providing a reason.",
      "quotes": [
        {
          "ref": "TMM/Part61/1/1/1",
          "quote": "1.1.2 Anyone can request all or specific documents that are on file."
        },
        {
          "ref": "TMM/Part61/1/1/1",
          "quote": "Under section 217A, no reason is required to be provided."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "IP Australia-generated correspondence generally becomes available for public inspection unless it contains material identified in Manual part 3.1.",
      "quotes": [
        {
          "ref": "TMM/Part61/5/5/1",
          "quote": "Correspondence generated by IP Australia will generally become available for public inspection if it does not contain material identified at part 3.1."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "No: the Manual does not treat a TM Headstart before payment of the Part 2 fee as a published trade mark application available for public inspection.",
      "quotes": [
        {
          "ref": "TMM/Part61/6/6/1",
          "quote": "As a TM Headstart is not a trade mark application and is not published under section 30 until the Part 2 fee has been paid any documents that are not part of the published application will not be made available for public inspection."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Payment of the Part 2 fee does not mean every Headstart document becomes public: the Manual excludes documents that are not part of the published application.",
      "quotes": [
        {
          "ref": "TMM/Part61/6/6/1",
          "quote": "any documents that are not part of the published application will not be made available for public inspection."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The supplied passages do not provide the complete list of prescribed documents or the contents of Manual part 3.1, so they do not establish an exhaustive list of public documents or exclusions.",
      "quotes": [],
      "authority": "none"
    },
    {
      "text": "For trade marks filed after 27 March 2007, the Manual identifies an FOI application as a route for seeking documents not considered available for public inspection, rather than promising their release.",
      "quotes": [
        {
          "ref": "TMM/Part61/1/1/2",
          "quote": "1.2.2 For trade marks filed after 27 March 2007, any document that is not considered Available for Public Inspection (API) can be applied for under the FOI Act."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0131",
    "GC-0046",
    "GC-0177"
  ]
}
